    b("rec-w5", "Precontractuele fase", "De onderhandelingsfase vóór een overeenkomst; niet in de wet geregeld, maar beheerst door de redelijkheid en billijkheid. Afbreken mag, tenzij dat door gerechtvaardigd vertrouwen of andere omstandigheden onaanvaardbaar is (CBB/JPO)."),
    b("rec-w5", "Negatief contractsbelang", "Schadevergoeding voor de gemaakte kosten bij onrechtmatig afgebroken onderhandelingen; het standaarduitgangspunt.", art="art. 6:162 BW"),
    b("rec-w5", "Positief contractsbelang", "Schadevergoeding voor de gederfde winst; alleen bij hoge uitzondering, bijvoorbeeld bij opzet of afbreken zonder reden.", art="art. 6:162 BW"),
    b("rec-w5", "Rompovereenkomst", "Een overeenkomst die al ontstaat zodra de essentiële punten vastliggen."),
    b("rec-w5", "Voorbehoud", "Clausule in de onderhandelingen, zoals 'pas na schriftelijke vastlegging' of 'na instemming van het bestuur', om gerechtvaardigd vertrouwen en een rompovereenkomst te voorkomen."),
    b("rec-w5", "Algemene voorwaarden", "Schriftelijk opgestelde bedingen, opgesteld om in meerdere overeenkomsten te worden opgenomen, behalve kernbedingen.", art="art. 6:231 sub a BW", ook=("AV",)),
    b("rec-w5", "Kernbeding", "Beding over de kern van de prestatie (prijs, product, dienst), dat nooit onder de algemene voorwaarden valt.", art="art. 6:231 sub a BW", ook=("kernbedingen",)),
    b("rec-w5", "Gebruiker", "De partij van wie de algemene voorwaarden afkomstig zijn.", art="art. 6:231 sub b BW"),
    b("rec-w5", "Wederpartij", "De partij die aan de algemene voorwaarden gebonden wordt.", art="art. 6:231 sub c BW"),
    b("rec-w5", "Onredelijk bezwarend", "Vernietigingsgrond voor een beding in AV, gelet op alle omstandigheden: aard en inhoud van de overeenkomst, hoe ze tot stand kwam en de kenbare belangen.", art="art. 6:233 sub a BW"),
    b("rec-w5", "Informatieplicht algemene voorwaarden", "De gebruiker moet de AV uiterlijk bij het sluiten ter hand stellen; anders is er geen redelijke mogelijkheid tot kennisneming en kan de wederpartij vernietigen.", art="art. 6:233 sub b jo. 6:234 BW", ook=("ter hand stellen", "terhandstelling")),
    b("rec-w5", "Zwarte lijst", "Bedingen die als onredelijk bezwarend gelden, zonder tegenbewijs; alleen voor consumenten.", art="art. 6:236 BW"),
    b("rec-w5", "Grijze lijst", "Bedingen die vermoed worden onredelijk bezwarend te zijn; de gebruiker mag het tegendeel bewijzen.", art="art. 6:237 BW"),
    b("rec-w5", "Reflexwerking", "Een kleine onderneming die vergelijkbaar is met een consument kan via de open norm toch de gedachte achter de zwarte en grijze lijst inroepen."),
    b("rec-w5", "Battle of forms", "Beide partijen verwijzen naar hun eigen AV; dan gelden die van wie het eerst verwijst, tenzij de ander ze uitdrukkelijk van de hand wijst.", art="art. 6:225 lid 3 BW", ook=("first-shot rule", "first shot rule")),
    b("rec-w5", "Eigendomsvoorbehoud", "De leverancier blijft eigenaar tot er betaald is; belangrijk bij faillissement.", art="art. 3:92 BW"),
    b("rec-w5", "Exoneratieclausule", "Beding waarmee een partij de eigen aansprakelijkheid beperkt of uitsluit, bijvoorbeeld tot de factuurwaarde.", art="toetsing aan art. 6:248 lid 2 BW", ook=("exoneratie", "exoneratiebeding")),
    b("rec-w5", "Beklemde detaillist", "Een detaillist mag niet vastzitten tussen ruimere aansprakelijkheid tegenover zijn klant en een exoneratie van zijn eigen leverancier.", art="art. 6:244 BW"),
    b("rec-w5", "Overmacht", "Een tekortkoming die de schuldenaar niet kan worden toegerekend; regelend recht, dus de gebruiker breidt het in de AV voor zichzelf vaak uit.", art="art. 6:75 BW"),
    b("rec-w5", "Arbitrage", "Geschilbeslechting waarbij arbiters beslissen en de rechter niet meer bevoegd is: sneller, meestal duurder."),

