    b("rec-w6", "Negatieve garantie", "Een garantie die de rechten van de koper eigenlijk inperkt; mag bij zakelijke koop, niet bij consumentenkoop.", art="art. 7:6 en 7:6a BW"),
    b("rec-w6", "Bewijsvermoeden", "Openbaart een gebrek zich kort na aflevering, dan wordt vermoed dat de zaak nooit conform was; volgens de huidige wet binnen één jaar (de slide noemt 6 maanden en art. 7:18 lid 2).", art="art. 7:18a lid 2 BW"),
    b("rec-w6", "Klachtplicht", "De koper moet binnen bekwame tijd klagen nadat hij het gebrek heeft ontdekt of had moeten ontdekken; voor een consument is binnen twee maanden in ieder geval op tijd.", art="art. 7:23 lid 1 BW"),
    b("rec-w6", "Recht van reclame", "Lijkt op ontbinding: de onbetaalde verkoper haalt de zaak terug, ook tijdens een faillissement, binnen 6 weken na opeisbaarheid en 60 dagen na aflevering.", art="art. 7:39, 7:41 en 7:44 BW"),
